input.command:
cd /app; cat > tests/prune_test.sh <<'EOF'
#!/bin/bash
# prune: a dry run on an empty root exits 0; audit logs live in var/audit and are kept 400 days (ADR-0015).
fail=0
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune dry-run"; fail=1; }
mkdir -p "$d/var/audit" "$d/var/log/shift"
touch -d '401 days ago' "$d/var/audit/old.log"
touch -d '399 days ago' "$d/var/audit/recent.log"
touch -d '60 days ago' "$d/var/audit/sixty.log"
touch -d '401 days ago' "$d/var/log/shift/shift.log"
out=$(RELAY_ROOT=$d bash bin/prune --dry-run)
[ "$out" = "$d/var/audit/old.log" ] || { echo "dry-run list: $out"; fail=1; }
RELAY_ROOT=$d bash bin/prune >/dev/null
[ ! -e "$d/var/audit/old.log" ] || { echo "old audit file kept"; fail=1; }
[ -e "$d/var/audit/recent.log" ] || { echo "recent audit file removed"; fail=1; }
[ -e "$d/var/audit/sixty.log" ] || { echo "60-day audit file removed"; fail=1; }
[ -e "$d/var/log/shift/shift.log" ] || { echo "shift log touched"; fail=1; }
rm -rf "$d"
exit $fail
EOF
bash tests/prune_test.sh; echo "exit $?"
